<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useMarketStore } from '../store'
import { usePolling } from '../usePolling'
import { compareNullable, fresh, matchesVolume, money, percent, price, ready, time } from '../format'
import type { MarketView } from '../types'
import FeatureValue from '../components/FeatureValue.vue'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import Pager from '../components/Pager.vue'
import CapitalDetail from '../components/CapitalDetail.vue'
const store = useMarketStore(); const { error } = usePolling(signal => store.refresh(signal), 2000)
const search = ref(''); const volume = ref(0); const readyOnly = ref(false); const redUp = ref(false)
const page = ref(0); const sort = ref('volume'); const descending = ref(true); const selectedId = ref<number | null>(null)
const columns = [['symbol','合约'],['price','价格 / USDT'],['1','1m'],['5','5m'],['15','15m'],['60','1h'],['1440','24h'],['volume','24h 成交额'],['priceZ','价格 RZ · 5m'],['volumeZ','成交量 RZ · 5m'],['percentile','价格分位']]
const horizons = [1,5,15,60,1440]
function value(m: MarketView): number | string | null | undefined { return sort.value === 'symbol' ? m.instrument.symbol : sort.value === 'price' ? m.price : sort.value === 'volume' ? m.volume24h : sort.value === 'priceZ' ? m.features.priceRobustZ5m.value : sort.value === 'volumeZ' ? m.features.volumeRobustZ.value : sort.value === 'percentile' ? m.features.pricePercentile.value : m.features.returns[sort.value]?.value }
const filtered = computed(() => store.assets.filter(m => m.instrument.symbol.toLowerCase().includes(search.value.trim().toLowerCase()) && matchesVolume(m.volume24h,volume.value) && (!readyOnly.value || ready(m))).sort((a,b) => compareNullable(value(a),value(b),descending.value)))
const paged = computed(() => filtered.value.slice(page.value*50,(page.value+1)*50))
const selected = computed(() => store.assets.find(m => m.instrument.assetId === selectedId.value))
watch([search,volume,readyOnly], () => { page.value=0 })
function changeSort(key: string) { descending.value = sort.value === key ? !descending.value : key !== 'symbol'; sort.value=key; page.value=0 }
function color(m: MarketView, h: number) { const f=m.features.returns[h]; if(!f || f.status!==0 || f.value===null) return 'muted'; return f.value>0 ? redUp.value?'negative':'positive' : f.value<0 ? redUp.value?'positive':'negative' : 'muted' }
const connected = computed(() => store.health.find(h=>h.health.name==='Binance WebSocket')?.status==='Healthy')
</script>
<template>
  <PageIntro eyebrow="BINANCE · USDⓈ-M PERPETUAL" title="市场，正在发生。" description="实时追踪 USDT 永续合约，观察价格、成交量与历史异常。"><span class="live-pill"><span class="status-dot"></span>{{ connected?'实时连接':'连接检查中' }}</span></PageIntro>
  <p v-if="error" class="radar-notice" role="alert">{{ error }} 已显示的数据为上次缓存，请核对源时间。</p>
  <div class="stats"><StatCard label="监控合约" :value="store.assets.length" foot="仅展示 TRADING · USDT 永续"/><StatCard label="价格可用" :value="store.assets.filter(m=>m.price!=null&&fresh(m.priceSourceTime)).length" foot="源时间距今不超过 30 秒"/><StatCard label="特征已就绪" :value="store.assets.filter(ready).length" foot="5m 价格 RZ 与成交量 RZ 可用"/><StatCard label="历史窗口" value="48 小时 / 1m" foot="5m · 7 天　15m · 30 天"/></div>
  <div class="section-heading"><h2>行情总览 <span>{{store.assets.length}}</span></h2><div class="refresh-text">每 2 秒读取 · {{time(store.updatedAt)}} <button class="text-button" @click="redUp=!redUp">{{redUp?'红涨绿跌':'绿涨红跌'}}</button></div></div>
  <div class="market-panel"><div class="toolbar"><label class="search"><span>⌕</span><input v-model="search" aria-label="搜索合约" placeholder="搜索合约，例如 BTC、ARIA"></label><select v-model.number="volume" aria-label="成交额筛选"><option :value="0">全部成交额</option><option :value="5000000">24h ≥ $5M</option><option :value="50000000">24h ≥ $50M</option></select><label class="checkbox"><input v-model="readyOnly" type="checkbox">仅已就绪</label><span class="results">{{filtered.length}} 个结果</span></div>
  <div class="table-scroll"><table><thead><tr><th v-for="c in columns" :key="c[0]"><button @click="changeSort(c[0]!)">{{c[1]}} <span class="sort">{{sort===c[0]?(descending?'↓':'↑'):'↕'}}</span></button></th><th>数据状态</th></tr></thead><tbody><tr v-for="m in paged" :key="m.instrument.assetId" :class="{selected:selectedId===m.instrument.assetId}" @click="selectedId=selectedId===m.instrument.assetId?null:m.instrument.assetId"><td><div class="symbol-cell"><span class="coin">{{m.instrument.baseAsset.slice(0,2)}}</span><span><b>{{m.instrument.baseAsset}}</b><small>{{m.instrument.symbol}}</small></span><span v-if="m.features.newListing" class="new-tag">NEW</span></div></td><td class="price">{{price(m.price)}}</td><td v-for="h in horizons" :key="h" :class="color(m,h)"><FeatureValue :feature="m.features.returns[h]" suffix="%"/></td><td>{{money(m.volume24h)}}</td><td><FeatureValue :feature="m.features.priceRobustZ5m"/></td><td><FeatureValue :feature="m.features.volumeRobustZ"/></td><td><FeatureValue :feature="m.features.pricePercentile" suffix="%"/></td><td><span class="data-state" :class="!fresh(m.priceSourceTime)?'stale':ready(m)?'valid':'warming'">{{!m.priceSourceTime?'等待数据':!fresh(m.priceSourceTime)?'已过期':ready(m)?'有效':'预热中'}}</span></td></tr><tr v-if="!filtered.length"><td colspan="12" class="empty">{{store.assets.length?'没有符合筛选条件的合约。':'等待 Binance 市场数据与合约同步。'}}</td></tr></tbody></table></div><Pager v-model="page" :total="filtered.length" :size="50">Unknown：历史不足或统计量未定义；过期值以灰色显示。</Pager></div>
  <section v-if="selected" class="detail"><div class="section-heading"><h2>{{selected.instrument.symbol}} · 数据详情</h2><button class="text-button" @click="selectedId=null">收起 ×</button></div><div class="detail-grid"><div><span>标记价格</span><strong>{{price(selected.markPrice)}}</strong></div><div><span>资金费率</span><strong>{{percent(selected.fundingRate==null?null:selected.fundingRate*100)}}</strong></div><div><span>历史样本 · 1m / 5m / 15m</span><strong>{{selected.minuteSamples}} / {{selected.fiveMinuteSamples}} / {{selected.fifteenMinuteSamples}}</strong></div><div><span>价格百分位依据</span><strong>{{selected.features.percentileBasis}}</strong></div><div><span>价格 SourceTime</span><strong>{{time(selected.priceSourceTime,true)}}</strong></div><div><span>价格 ReceivedTime</span><strong>{{time(selected.priceReceivedTime,true)}}</strong></div><div><span>Funding SourceTime</span><strong>{{time(selected.fundingSourceTime,true)}}</strong></div><div><span>资产 ID</span><strong>{{selected.instrument.assetId}}</strong></div></div></section>
  <CapitalDetail v-if="selected" :market="selected" /><section class="providers"><div class="section-heading"><h2>数据源状态</h2><span class="refresh-text">独立健康检查 · UTC</span></div><div class="provider-grid"><div v-for="h in store.health" :key="h.health.name" class="provider"><div><b>{{h.health.name}}</b><span class="health" :class="h.status.toLowerCase()">{{h.status}}</span></div><span>最近成功 {{time(h.health.lastSuccess,true)}}</span><span>错误 {{h.health.errorCount}} · 延迟 {{h.health.latencyMs??'—'}} ms</span><p v-if="h.health.error" class="provider-error">{{h.health.error}}</p></div></div></section>
</template>
